using System;
using MegaCrit.Sts2.Core.Helpers;
using CharacterBosses;

namespace CharacterBosses.Core;

/// <summary>
/// 构建指纹 + 一次性启动日志。
///
/// 用途：
///   · `Tag` 写进日志与上传数据的 `mod` 字段 ⇒ 拿到玩家日志就能确认「他跑的是哪一版」；
///   · <see cref="LogOnce"/> 由 `BossFrameTickPatch` 在第一帧调一次（那时所有程序集都加载完了），
///     顺手装「薄荷尖塔」的伤害预测兼容（见 <c>Core.MintySpireDamagePreviewCompat</c>）。
///
/// ⚠ 改版本时**两处一起改**：这里 + `src/CharacterBosses.json` 的 `version`。
/// </summary>
public static class BuildInfo
{
    /// <summary>构建指纹（日志/数据表里用）。每次改动都要 +0.0.1 并写一句改了什么。</summary>
    public const string Tag = "v0.2.567 / 2026-11-10（抉择储：新增**铸造对账日志** —— 用户「怎么感觉铸造有问题？…君王之剑第四回合应该是 10+10+8+5=33，我看到的是 37」。君王之剑伤害 = 卡面 10 + 本场铸造之和；37 = 33 + 4 正好是「淬炼刀刃」进阶 9 升级后的铸造 12（`ForgeVar(8)` + `UpgradeValueBy(4)`，未升级才是 8）。为了让下次一眼对账，`PlayOne` 每打出一张带 `Forge` 变量的牌就打一行 `铸造：<牌>（升级=…）铸了 N ⇒ 君王之剑当前伤害 M`，配合既有的 `击剑指南：战斗开始铸造 10…` 就能逐笔核出 M。另含 v0.2.566 / 2026-11-10（抉择储剧本第三轮订正（用户）：第 3 回合 = 招架、星尘、汇流+、防御（3 费）；第 4 回合 = 君王之剑、隐秘藏品、防御（没费）（3 费）；第 5 回合只有 **2 费**（天际钻头 X=2；选了星位序列则 X=8 ⇒ 16 段，星位序列下面的预告也随之变成 8×14））。另含 v0.2.565 / 2026-11-10（抉择储：「第一回合选隐秘藏品的情况下，第二回合的辐射没有计算隐秘藏品在回合开始时给的星」—— 「下回合 +N 辉星」（`StarNextTurnPower`）是**她回合开始时**到账的，对本回合而言就是「本回合获得过的辉星」⇒ 规划期现在把它**同时**算进星预算 `stars` 与 `starsGainedThisTurn`（辐射的段数口径）；星尘的星数口径也一并包含它）。另含 v0.2.564 / 2026-11-10（抉择储：①**星尘/辐射的段数现在真的生效了** —— 用户「辐射仍没有提前计算本回合会获得的辉星数。星尘仍然没有正确显示段数」：上一版只把 `starHits` 传给规划期那一处，而 `PrepareTurn` 规划完**紧接着**就调 `BladesGrowth.RecomputeAll` 重算、出牌期每张牌前还会再重算 ⇒ 全被「历史口径」覆盖回 1 段。现在把它定死存进 `PlannedPlay.StarHits`，两条重算路径（`BladesGrowth.RecomputeAll` / `CharBossMonster.RefreshPlannedIntents`）都原样再用（和 `SmokePerHit`/`LetterOpenerHit` 同一套做法）；②**进阶 9 不再升级共鸣**（用户订正）——`BossDefs` 的进阶表与第 11 回合剧本那张都改回未升级）。另含 v0.2.563 / 2026-11-10（抉择储意图/资源四处修正：①**星尘**（X 星费，把身上所有辉星花光 ⇒ 一星一段）与**辐射**（段数 = 本回合获得过的辉星数）现在按剧本顺序把星数递进 `BossIntentBuilder.IntentsFor(starHits:)`（规划期历史是空的，原来恒显示 1 段）；②规划期新增 `starsGainedThisTurn` 记账；③**汇流/淬炼刀刃的「下回合 +1 能量」不再当成立刻到手**（`DeferredEnergyCard`），修第 9/10 回合最后那张本该死费的隐秘藏品被画成还能打；④天际钻头 <<把这一回合剩余能量全部花光>> 改由剧本 `ScriptCard.SpendsAllEnergy` 明说（不再靠 `EnergyCost.CostsX` 猜），修第 5 回合「君王之剑」被画成能打；⑤`XHitBonus` 改成**规划期算出的 cost 优先**（以前优先读已捕获的 X，可能残留上一张牌的值 ⇒ 第 13 回合只剩 1 费却画 2 段），并给天际钻头补上「X≥4 翻倍」；⑥天钻 X=0/星尘辐射 0 段时不再画一条 0 点攻击意图。另含 v0.2.562 / 2026-11-10（抉择储：「抉择，抉择」不再被提前打断 —— 用户「如果我选的太慢，他的这个回合会结束并使我的下个回合开始。应该让储君的这张牌不会被提前打断，玩家选完之前所有其他进程都应该停着。也不要因为这张牌卡了很久就把它当bug（只让抉择抉择受到这些豁免）」。两处一起改：①`PlayOne` 那个 5 秒 AutoPlay 兜底对它**不计时**（一直 await 到玩家选完，期间她整个回合停在这一句，其它 Boss/玩家回合都排在后面）；②`StrayBossCardQueuePatch.Reap()` 在等待期间**暂停**（新增 `HoldReap`）—— 慢车道 4Hz 会把它当成「怪物打出的残留卡面」从出牌队列里摘掉，等于提前打断她这一手；③`BossFrameTickPatch.WatchPlayQueue` 不再对 DECISIONS_DECISIONS 报「⚠ 出牌队列滞留」（和数据收集里那条「玩家自己在选牌」的豁免同一性质）。另含 v0.2.561 / 2026-11-10（抉择储：星位序列那条「天际钻头会多打多少」改用**原版意图节点**（`MultiAttackIntent` → `NIntent`，与其它意图同一套图标/字体），不再是我自造的 Label（用户「你用原版的，别自己瞎搞」）；它仍然**不放进 `PlannedPlay.Intents`** ⇒ 不进原版 `MoveState.Intents`，薄荷尖塔不会重复统计（用户「只改一下不让薄荷尖塔记录就行了」）。顺带：第 5 回合的钻头是常驻的、没有 `OnlyIfChosenCard`，`FindChoiceDrill` 现在按「X 费牌」也认得出它，所以那一手也会画预告。另含 v0.2.560 / 2026-11-10（抉择储第二轮：①第 6 回合按用户订正改成 2 费「辉光、辐射、淬炼刀刃、收集光辉（没费）」；②那 5 张候选技能牌**压暗但画意图** —— 铸墙=守势+强化、隐秘藏品=强化、共鸣=策略+强化、震荡波=策略（`ScriptCard.ForceIntents` + `PlannedPlay.DimWhenShown`，手牌栏 `Bright` 不再只看「在不在 DisplayPlays 里」）；星位序列那一栏标出「选它会多打多少」（如第一回合 8×12 = 天际钻头 8×6 不变、选后 8×12，即多 6 段），这条是**标签不是意图** ⇒ 不进原版 MoveState.Intents，薄荷尖塔的伤害统计不会算它（`PlannedPlay.DrillPerHit/DrillGainHits` + `BossHandCard.AddDrillGainLabel`）；③震荡波本身带「消耗」，给它附魔「灵魂之力」（候选那张与第 12 回合那张都加）。另含 v0.2.559 / 2026-11-10（三层储君 3 号「抉择储」（用户设计）：特殊效果「指导」= 她打「抉择，抉择」时**由玩家**（多人时是被他锁定的那位）替他挑那张要被重复打出 3 次的牌 —— 用知识恶魔那套 CardSelectCmd.FromChooseACardScreen，选完他才继续打后面的牌（Patches/ChoiceRegentPickPatch 接管 CardSelectCmd.FromHand；选牌前用 SuspendSelectorForTest 把自动选择器摘掉，否则界面根本不会出现；挑中的那张记进 Core/ChoiceRegent）。13 回合剧本、9～13 循环（Core/ChoiceRegentScript）；遗物 = 天赋君权/涅奥的祝福/准备背包/燃烧木棍/玻璃眼珠/击剑指南/王室印章/钗/灯笼（锚→灯笼、胜券在王→王国资产、崇拜全难度升级）；逐回合写死能量（1、2、3、5、7、8、10、11 = 3 费，12 = 4 费，其余 2 费）；第 1 回合「天际钻头」只有玩家选了星位序列（3 次 ×+2 费）才打得出去（ScriptCard.OnlyIfChosenCard + CharBossMonster.RunChoiceFollowUpsAsync 在选择落地后补打），第 5 回合的钻头一定打出（X = 出手时的剩余能量，X≥4 翻倍照原版）；16 语言文案 + 藏品天际钻头 + 能力面板占位）。另含 v0.2.558 / 2026-11-10（顶栏两个 Boss 头像一样：用户「剪影是一个亡灵契约师和一个储君，顶栏却两个亡灵契约师」—— 两颗图标各自按**遭遇**解析角色，而第二槽的遭遇很容易解析回第一槽那只角色（第二槽复用第一槽遭遇 / `SecondBossEncounter` 读取兜底没换成伙伴那套）。现在两颗解析出同一只角色时，第二颗改用**我们阵容里的第二只设计**（多人同场 = 本场阵容 partner；进阶 10 = 该幕第 2 场阵容主角色），`BossLineups.LineupNow()` 是新加的 UI 用包装。另含 v0.2.557：，日志直接指出的：`power.Applier` 不能当判据 —— 日志 22:56:25 显示 `STRENGTH_POWER −2 → 目标=玩家 钩子施加者=… power.Applier=…(是我=False)`；原因是 `StrengthPower` **复用已有实例**（玩家早先给自己 +1 力量时建的那份，实例上的 Applier 一直是玩家自己），而虚弱/易伤每次都新建实例所以一直正常。现在判据改成「钩子参数 applier 是她」为主，只有 applier 为空时才回退到 `power.Applier` 且要求 amount > 0（这样衰减 −1 不会被误判成她给负面）。诊断行把两个施加者分开打印。另含 v0.2.556：：日志证明钩子**确实被派发**（`吞噬生命钩子：power=STRENGTH_POWER amount=-2 …`），而 `VULNERABLE +2`/`WEAK +1` 都能正常打出 9 点 ⇒ 掐在「是不是负面」这一步：`GetTypeForAmount(-2)` 对 `STRENGTH_POWER` 认不出负面。现在与 `BossIntentBuilder.ClassifyPowers` 同一把尺子：`harmful = kind == Debuff || amount < 0`。并把诊断行扩成一次打全（目标 side/Monster、施加者是否是她、GetTypeForAmount 结果、是否 ITemporaryPower），下次一眼定位。另含 v0.2.555：改由**吞噬生命**（她必然带着的特殊效果）结算 —— 原来放在 `SleightOfFleshBossPatch` 里接管她身上那层 `SleightOfFleshPower` 的回调，实测有一次那次派发整段没走到（22:42 的 `STRENGTH_POWER −2` 连日志都没有）⇒ 9 点整条丢了；现在 `BossDevourLifePower` 里一次性做「+4 格挡 + 有血肉戏法就对该玩家补 Amount 点无来源伤害」，那条 patch 只保留「压掉原版，免得她自伤」+ 加了一行钩子诊断日志。②**Boss 的随从（奥斯提）不吃任何负面效果**（`BossPetNoStrengthLossPatch`）：以前只在「施加者是真人玩家」时才拦，于是她自己/她的牌给的负面（王储的临时减力量等）照样落到随从身上；现在改成「负面效果一律拦（任何来源）+ 真人玩家的正面效果也拦」。另含 v0.2.554：：查「玩家给 Boss 上负面时，头上不浮图标、也没有施加音效」。反编译 `NCreature.OnPowerIncreased` 第一行是 `if (silent || !CombatManager.IsInProgress) return;`（图标+音效一起没），而音效另外还要求 `power.ShouldPlayVfx`（= `Owner.IsAlive && IsInProgress && IsVisible`，`IsVisible` = `Target==null || IsMe(Target) || Target.IsEnemy`）。新增 `BossPowerApplyTracePatch`：只在 `PowerCmd.Apply` 的目标是 CharacterBosses 的 Boss 时打一行 `PowerApply 诊断：<power> <amount> → <她>（施加者=… silent=… IsInProgress=… ShouldPlayVfx=… IsMe=… Side=…）`（限 40 行）。复现一次把那几行发回来就能定位是哪一条被掐。另含 v0.2.553：：血肉戏法/吞噬生命判定「负面」时写成了 `amount <= 0`，而「失去力量」这类负面是**负数**送进来的（`PowerCmd.Apply<StrengthPower>(…, -2, …)` ⇒ amount = -2）⇒ 命运同担那条 9 点被整条挡掉、她也不加格挡。原版判据本就是 `amount != 0`，现在两处都改成「只排除 0，是不是负面交给 `GetTypeForAmount`」。另：血肉骨的能力面板按用户给的数据补齐（单体强/群攻强/单体高压 3、5、11/群体高压 4、10/特殊效果类型：自身/群体减益极强/群体增益弱）。另含 v0.2.552：改成**策略 + 牺牲**：它的两个变量 `PlayerStrengthLoss`/`EnemyStrengthLoss` 都是普通 `DynamicVar` 而不是 `PowerVar<>` ⇒ `ClassifyPowers` 什么都认不出来，会掉到「技能牌兜底 = 强化」上（蓝色上箭头）。现在把 `SHARED_FATE` 同时加进 `ForceDebuffCards`（给敌人扣力量 = 策略/红下箭头）与 `SacrificeCards`（自己也扣力量 = 牺牲/蓝下箭头）；顺带它既然算「策略」，血肉戏法那 +9 也会跟着显示（它确实会给那个玩家上负面）。另含 v0.2.551：：①**招架盾 → 锚**（战斗开始 10 格挡），特殊效果警告文案同步去掉「招架盾」；②11 回合剧本再重排 —— 1 血肉戏法+鬼火+防御 / 2 吸引仇恨+摧残 / 3 打击+恐惧+ / 4 违逆+防御+苦难 / 5 护卫+出击+防御(没费) / 6 命运同担+防御×2 / 7 吸引仇恨 / 8 摧残+防御+防御(没费) / 9 防御+恐惧+ / 10 违逆+防御+苦难 / 11 护卫+出击+防御(没费)，循环仍 7～11；③**摧残在玩家身上改成与虚弱/易伤同步**（`DebilitateTicksWithWeakPatch`）—— 反编译：`VulnerablePower` 是 `side == Enemy ⇒ TickDownDuration`，而 `DebilitatePower` 是「持有者自己这一侧回合结束 ⇒ Decrement」⇒ 玩家身上摧残玩家回合一结束就掉 1，少撑一个回合；现在玩家身上的摧残也只在**敌方**回合结束掉 1。另含 v0.2.550：：**撕碎 → 玷污**（`Defile`，1 费 13 伤，升级 17）—— 第 4、11 回合各换一张，能量账不变；卡组里对应替换。另含 v0.2.549：：①**进阶 9 = 只升级摧残**（去掉恐惧）；②剧本重排 —— 2 出击+恐惧+(没费打击) / 3 违逆+防御+苦难 / 5 吸引仇恨(不升级)+摧残 / 6 打击+防御+命运同担 / 7 吸引仇恨 / 9 防御+恐惧+ / 10 违逆+防御+苦难 / 11 撕碎+护卫+防御，循环仍 7～11；③卡组按单回合最大张数重算（14 张：防御×2、打击×2，其余各 1）。另含 v0.2.548：：`UNLEASH` 的伤害是 `CalculationBase + ExtraDamage × 奥斯提当前生命`，而意图数字只在**面板重建**时算 —— 玩家在她回合外打掉/治好奥斯提、或奥斯提被召唤/死亡时，能力层数一个都没变 ⇒ `RefreshIntentsIfPowersChanged` 的指纹不变 ⇒ 不重建 ⇒ 数字停在旧值。现在把**她的奥斯提**（存活 + 当前生命 + 最大生命）也拼进那个每帧比对的指纹，一变就 `IntentsDirty` ⇒ 下一帧按新血量重算；并加了一行限流日志 `意图重算（能力/奥斯提变化）：… → …` 便于验证。另含 v0.2.547：（用户「更改部分意图和进阶效果」）：11 回合剧本按新稿重排 —— 2 出击+防御+防御 / 3 违逆+恐惧+苦难 / 4 撕碎+防御+防御 / 5 吸引仇恨+ / 9 恐惧+防御+苦难 / 10 撕碎+护卫+防御 / 11 防御+违逆+打击，循环仍是 7～11；**进阶 9 改成升级恐惧、摧残**（之前误写成苦难/出击/摧残）；卡组按单回合最大张数重算（护卫×2、防御×2、出击×2、违逆×2、恐惧×2、苦难×2、撕碎×2、打击×2，吸引仇恨/摧残/命运同担各 1）。另含 v0.2.546：：①多人时招架盾只打她锁定的那位玩家（原版是 `HittableEnemies` 里随机一个，会打到没被锁的人）——`ParryingShieldBossPatch` 按原版条件结算、目标固定成 `BossLockOn.TargetFor`；②命运同担不再打到自己 —— 反编译该卡除了让目标掉力量还会**让她自己掉力量**，而她自己的生物 `Side==Enemy` 正好满足原版血肉戏法的 `power.Owner.IsEnemy` ⇒ 她给自己上负面时被自己的血肉戏法打 9 点；现在 `SleightOfFleshBossPatch` 对「持有者是我们 Boss」的情况**整条接管**，只对真人玩家结算；③进阶 9 不再升级出击（保留苦难、摧残）；④招架盾预测修正 —— 以前无条件把她**当前**格挡算进去，而格挡在她自己回合开始会清空 ⇒ 玩家回合里那份是上回合剩下的、马上就没，现在只在「她回合内」才计入；并加了一行预测明细日志（当前格挡/牌/骇人头盔/吞噬生命各自贡献）。另含 v0.2.545：NECROBINDER_FLESH —— 11 回合剧本 + 7～11 循环，遗物缚魂命匣/涅奥的祝福/骇人头盔/招架盾，特殊效果「吞噬生命」（她每给玩家一个负面就 +4 格挡，`BossDevourLifePower`）；①`SleightOfFleshBossPatch` 让血肉戏法对她生效（原版条件是 `power.Owner.IsEnemy`＝绝对阵营，玩家是 Side.Player ⇒ 对影子玩家永远 false）；②会施加减益的牌，意图里补上血肉戏法的 9 点（无来源）；③回合结束格挡预测 ≥10 时，在独立意图位（电球/炸弹那一行）显示招架盾的 6 点（`FleshBone.EndOfTurnBlock` 算了 plan 里的格挡 + 骇人头盔 + 吞噬生命）；④多人「苦难」把被锁玩家负面传给其他玩家 ⇒ 其他玩家意图显示 血肉戏法×种类数；⑤多人把吸引仇恨换成骸骨军团（`MultiplayerCardSwap` act0 行）；⑥16 语言文案（特殊效果含「无来源伤害 / 为你而死不挡」警告）+ 藏品命运同担 + 能力面板。另含 v0.2.544：：`BossStatusRow.Fill` 里能量球是按影武者缓存的节点，旧代码只在「已挂在本行」和「完全没有父节点」两种情况把它排进 `target`，一旦它挂在**另一条（残留的/备用/不可见的）状态栏**上就既不搬运也不登记 ⇒ 这一行没有能量球、`EnergyCenterX` 一路返回 0（14:07 的 mod_log 里 `独立意图定位：能量中心 x=0` 反复出现，且同帧有 `rowChildren=5/5` 与 `4/4` 两条 Fill）。现在：①「可复用」判定再按影武者缓存兜一层，避免把行里那颗正在用的球当垃圾清掉；②父节点已失效/排队销毁/**不可见**时搬过来；③主面板（`primaryRow`，可见）一律抢过来，只有备用行才「别抢还活着的那条」。另含 v0.2.543：：`PlaceExtraIntents` 原来只用「能量栏中心 − 行宽/2」，而它和卡面下方那排意图**同一高度**，牌少或这一行偏宽时左缘会滑进卡牌意图区（用户「第二回合电球被动过于偏左，和扫荡射线叠在一起」）⇒ 现在先逐格测量所有卡牌意图行的真实右缘（意图行在卡片内部且整体左移过、内容还可能比卡面宽，不能拿卡面右缘当边界），再让这一行左缘至少落在它右边 Gap 处；彩虹机的整体左移算在 max 之前。另含 v0.2.542：改成走「超能光束」那层原版 buff：每满 3 张牌给她 1 层 `HyperbeamFocusDownPower`（基类 `TemporaryFocusPower`，IsPositive=false）—— 应用时原版立刻 −1 集中、她自己回合结束时原版移除该层并把集中全数还回来、且它是 debuff 所以人工制品能挡，图标文案也是原版那套；107 没有这个类型（107 的超能光束是直接 −3、不返还）⇒ 用 `#if STS2_111 / #else` 保持老写法自己扣自己还。另含 v0.2.541 四项：①语音音量 -4dB → -0.5dB（振幅 ×1.5，用户「有点小，调大 50%」）；②预借时间不再统计**自动打出**的牌（`CardPlay.IsAutoPlay` 或 `Resources.EnergySpent == 0` ⇒ 没花能量不计），修「历史书打出攻击牌会错误增加预借时间计数」；③引雷针计数改存字段、图标数字钳在 1..3（还差几张），修「打三张牌集中不掉」—— 根因是玩家回合开始时 `Apply(-Amount)` 把数量减到 0，原版 `PowerCmd.ModifyAmount` 见 `ShouldRemoveDueToAmount()` 直接**把整条 power 移除**了；④电球机暴风雨的激发意图闪一下就没了（另记）；另含 v0.2.540：按用户第二轮要求改：①**时机延后** —— 不在出牌前播，改在 `Hook.AfterDamageGiven`（伤害真正落地那一刻）才播；②**不再每张攻击牌都喊** —— 只认 8 张：痛击 BASH / 完美打击 PERFECTED_STRIKE / 突破 BREAKTHROUGH / 全身撞击 BODY_SLAM / 巨石 GIANT_ROCK / 彼岸咆哮 HOWL_FROM_BEYOND / 闪电霹雳 THUNDERCLAP / 欺凌 BULLY；③每回合最多一次，多段牌只在第一段响（`CardCmd.AutoPlay` 前缀挂待播标记 + 上述伤害钩子配音清标记，两版本签名一致）；④彼岸咆哮那种回合结束从消耗堆自动打出的也算，因为挂在 AutoPlay 而不是我们的 PlayOne 上。上一版 v0.2.539 首次加入：：一代崩坠那 6 句 VO_IRONCLAD_1a/1b/1c/2a/2b/2c 已打进我们自己的 PCK —— ①每回合**首次打出攻击牌**时随机喊 1a/1b/1c（`CharBossMonster.PlayOne` 在 AutoPlay 之前播，`AttacksPlayed==0` 即本回合首张，与出牌同时出声）；②**死亡**时随机喊 2a/2b/2c（`HasDeathSfx` 覆写成 false 压掉原版那条 FMOD 事件 + `NCreature.StartDeathAnim` 后置播我们的 ogg，同生物只喊一次）；③覆盖所有 IroncladBoss 子类（怒/打击/出血/杂耍/易伤/巨石）。另含 v0.2.538 的亡魂牵引段数与致死性顺序修正（用户实测预览 7×3、真实 6×4）：①**段数**补上「本回合还没打出去的虚无牌」—— 致死性是虚无牌而它排在亡魂牵引前面，规划期战斗历史里还没有它，改由 `BossIntentBuilder.PlannedEtherealBefore` 按 `boss.Plan` 自己数（三条重算路径自动一致，打完即从 Plan 摘掉⇒不会双算、也不会漏传参）；②致死性 +50% 的**顺序**改成「先走完原版伤害管道（力量/虚弱/易伤）→ 再乘倍率 → 向下取整」，与真实结算同序（(5+力量−1)×1.5=6）；旧写法先把牌面 ×1.5 再减力量会多 1 点。另含 v0.2.537 的虚无骨四处收口：①女妖之嚎不再多画「强化」意图（`NoBuffIntentCards` 点名 BANSHEES_CRY）⇒ 第 4 回合 = 攻势+策略、第 7 回合 = 只有攻势；②亡魂牵引的段数补上「本回合已打出的虚无牌」—— 致死性本身是虚无牌，规划期历史里还没有它（`BossScriptPlanner.etherealPlanned` 按剧本顺序累加，只给 PULL_FROM_BELOW）；③致死性的 +% 以前只给「奥斯提那几张」手工补，现在**她身上还没这层 power** 的普通攻击牌（正是规划期）也补一次，power 真上身之后走原版管道不双份；④配置界面补上虚无骨的能力面板（循环 7～10 / 单体极强 / 群攻很强 / 单体高压 4、7、9 / 群体高压 4、7 / 全局））";

    private static bool _logged;

    /// <summary>打一行「构建：…」，并第一次装上运行时才能装的东西（薄荷尖塔兼容等）。只做一次。</summary>
    public static void LogOnce()
    {
        if (_logged) return;
        _logged = true;

        try { Logger.Log($"[CharBoss] ===== CharacterBosses 构建：{Tag} ====="); }
        catch { /* 忽略 */ }

        // 双版本兼容层（v0.107 正式版 / v0.111 beta）：把游戏版本和各项 API 探测结果打出来，
        // 以后一看日志就知道这一把跑在哪个版本、哪些功能被跳过了。
        try { Core.GameCompat.LogOnce(); }
        catch (Exception e) { try { Logger.Log("[CharBoss] 兼容层探测失败（忽略）: " + e.Message); } catch { } }

        // ★★ v0.2.533（玩家 2026-11-09：「炼药猎的**群蛇形态多人时会打其他玩家**」）：
        //   `SerpentFormLockOnPatch` / `DarkOrbLockOnPatch` / `PlayerEffectExemption` / `BossBlockAbsorbPatch`
        //   这几套是**手写 Harmony**（要挂 async 状态机的 `MoveNext`，没法用 `[HarmonyPatch]` 特性），
        //   靠自己的 `TryInstall()` 安装 —— 而**这四个 TryInstall 一个调用点都没有**，
        //   也就是说它们**从来没生效过**（日志里也从来没有「已挂 N 个状态机」那一行）。
        //   ⇒ 「多人时群蛇形态随机打人」就是收窄逻辑压根没挂上。
        //
        //   只安装**明确对应「随机/球被动只打被锁定那位」**的两套（用户口径）：
        //     · SerpentFormLockOnPatch：群蛇形态（炼药猎的「蛇形」牌）
        //     · DarkOrbLockOnPatch：黑暗充能球的被动
        //   `BossBlockAbsorbPatch` **故意不装**：用户明确要求「只有炼药猎能挡失去生命」，
        //   那件事由 `BrewerBossBlockableHpLossPatch` 负责（装了这个就变成所有 Boss 都能挡）。
        //   `PlayerEffectExemption` 也先不装（会改变「玩家施加的效果打谁」，需要单独确认）。
        try { Patches.SerpentFormLockOnPatch.TryInstall(); }
        catch (Exception e) { try { Logger.Log("[CharBoss] 群蛇形态锁定补丁安装失败（忽略）: " + e.Message); } catch { } }
        try { Patches.DarkOrbLockOnPatch.TryInstall(); }
        catch (Exception e) { try { Logger.Log("[CharBoss] 黑暗球锁定补丁安装失败（忽略）: " + e.Message); } catch { } }

        // 薄荷尖塔（MintySpire2）的「即将受到的伤害」兼容：它可能排在我们后面加载，
        // 所以等所有程序集都到位后再反射挂补丁（拿不到就安静跳过）。
        try { Core.MintySpireDamagePreviewCompat.TryInstall(); }
        catch (Exception e) { try { Logger.Log("[CharBoss] 薄荷尖塔兼容安装失败（忽略）: " + e.Message); } catch { } }
    }
}
